mapper.select:
select
a.triphase_id,
a.triphase_name,
a.device_mete_id,
a.device_id,
a.custom_id,
a.instance_one_id,
a.instance_one_name,
a.one_cruise_device_name,
a.instance_two_id,
a.instance_two_name,
a.two_cruise_device_name,
a.instance_tri_id,
a.instance_tri_name,
a.tri_cruise_device_name,
a.identify_type,
a.identify_son_type,
a.triphase_type,
a.warn_threshold,
a.warn_level
from t_cruise_triphase_rule a
where 1 = 1
 and a.triphase_id = #{triphaseId, jdbcType=BIGINT}
 and a.triphase_name = #{triphaseName, jdbcType=VARCHAR}
 and a.device_mete_id = #{deviceMeteId, jdbcType=BIGINT}
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.custom_id = #{customId, jdbcType=VARCHAR}
 and a.instance_one_id = #{instanceOneId, jdbcType=BIGINT}
 and a.instance_one_name = #{instanceOneName, jdbcType=VARCHAR}
 and a.one_cruise_device_name = #{oneCruiseDeviceName, jdbcType=VARCHAR}
 and a.instance_two_id = #{instanceTwoId, jdbcType=BIGINT}
 and a.instance_two_name = #{instanceTwoName, jdbcType=VARCHAR}
 and a.two_cruise_device_name = #{twoCruiseDeviceName, jdbcType=VARCHAR}
 and a.instance_tri_id = #{instanceTriId, jdbcType=BIGINT}
 and a.instance_tri_name = #{instanceTriName, jdbcType=VARCHAR}
 and a.tri_cruise_device_name = #{triCruiseDeviceName, jdbcType=VARCHAR}
 and a.identify_type = #{identifyType, jdbcType=INTEGER}
 and a.identify_son_type = #{identifySonType, jdbcType=INTEGER}
 and a.triphase_type = #{triphaseType, jdbcType=INTEGER}
 and a.warn_threshold = #{warnThreshold, jdbcType=VARCHAR}
 and a.warn_level = #{warnLevel, jdbcType=INTEGER}

